<?php
if(PHP_SAPI!=='cli'||getenv('DB_NAME')!=='sukamulya_ui_test')exit(1);
date_default_timezone_set('Asia/Jakarta');$db=new mysqli('localhost','root','','sukamulya_ui_test');$creds=json_decode(file_get_contents(__DIR__.'/../tmp/adminqa/sub-browser.json'),TRUE);
function editor_check($ok,$name){if(!$ok)throw new RuntimeException($name);echo 'PASS '.$name.PHP_EOL;}
class EditorHttp{
 public $curl,$code,$html;function __construct(){$this->curl=curl_init();curl_setopt_array($this->curl,array(CURLOPT_RETURNTRANSFER=>TRUE,CURLOPT_COOKIEFILE=>'',CURLOPT_TIMEOUT=>25,CURLOPT_PROXY=>''));}
 function go($path,$fields=NULL){if($fields!==NULL){foreach(curl_getinfo($this->curl,CURLINFO_COOKIELIST) as $cookie){$p=explode("\t",$cookie);if(($p[5]??'')==='csrf_sukamulya_cookie')$fields['csrf_sukamulya']=$p[6];}curl_setopt_array($this->curl,array(CURLOPT_POST=>TRUE,CURLOPT_POSTFIELDS=>http_build_query($fields)));}else curl_setopt($this->curl,CURLOPT_HTTPGET,TRUE);curl_setopt($this->curl,CURLOPT_URL,'http://127.0.0.1:8097/'.$path);$this->html=curl_exec($this->curl);$this->code=curl_getinfo($this->curl,CURLINFO_HTTP_CODE);if(preg_match('/Fatal error|A PHP Error|A Database Error|Severity:/',$this->html))throw new RuntimeException('PHP error '.$path);return $this;}
 function login($platform){global $creds;$path=$platform?'platform/login':'admin/login';$this->go($path);return $this->go($path,array('username'=>$creds[$platform?'platform':'username'],'password'=>$creds['password']));}
}
$a=new EditorHttp;$a->login(FALSE);$a->go('platform/paket');editor_check(in_array($a->code,array(302,303,307),TRUE),'RT administrator cannot access package editor');
$p=new EditorHttp;$p->go('platform/paket');$p->login(TRUE);$p->go('platform/paket');editor_check($p->code===200,'Platform editor opens');
$data=array('action'=>'save','plan_id'=>0,'version'=>0,'name'=>'Paket Editor Uji','price'=>'125000','duration_days'=>365,'description'=>'Semua fitur yang dipilih, ditambah:','benefits'=>"Pendampingan awal\nDukungan pengaturan",'theme'=>'violet','sort_order'=>5,'features'=>array('social_aid'),'is_active'=>1);
$p->go('platform/paket',$data);editor_check(in_array($p->code,array(302,303,307),TRUE),'Create editable offer');$id=(int)$db->query('SELECT MAX(id) id FROM subscription_plans')->fetch_assoc()['id'];
$row=$db->query('SELECT * FROM subscription_plan_details WHERE plan_id='.$id)->fetch_assoc();editor_check($row['theme']==='violet'&&(int)$row['version']===1&&count(json_decode($row['benefits_json'],TRUE))===2,'Benefits, colour, order and version saved');
$data=array_merge($data,array('plan_id'=>$id,'version'=>1,'name'=>'Paket Editor Revisi','price'=>'150000','features'=>array('social_aid','family_card')));$p->go('platform/paket',$data);$r=$db->query('SELECT * FROM subscription_plans WHERE id='.$id)->fetch_assoc();editor_check($r['name']===$data['name']&&(float)$r['price']===150000.0,'Unassigned package edits in place');
$p->go('platform/paket',$data);editor_check($p->code===200&&strpos($p->html,'Paket sudah diubah')!==FALSE,'Stale edit rejected');
$a->go('admin/langganan');editor_check(strpos($a->html,'150.000')!==FALSE&&strpos($a->html,'Pendampingan awal')!==FALSE&&strpos($a->html,'sp-violet')!==FALSE,'Tenant cards render persisted edits');
foreach(array(array('price'=>'-1'),array('features'=>array('fake_feature')),array('duration_days'=>0),array('benefits'=>str_repeat("Manfaat\n",13))) as $bad){$p->go('platform/paket',array_merge($data,array('version'=>2),$bad));editor_check($p->code===200,'Invalid package values rejected');}
$actor=0;$start=date('Y-m-d H:i:s',time()-60);$end=date('Y-m-d H:i:s',time()+86400);$s=$db->prepare("INSERT INTO tenant_subscriptions(tenant_id,plan_id,status,starts_at,ends_at,reason,created_by) VALUES(1,?,'ACTIVE',?,?,'Editor snapshot test',?)");$s->bind_param('issi',$id,$start,$end,$actor);$s->execute();$sid=$db->insert_id;
$data=array_merge($data,array('version'=>2,'name'=>'Paket Revisi Baru','features'=>array('family_card')));$p->go('platform/paket',$data);$newid=(int)$db->query('SELECT MAX(id) id FROM subscription_plans')->fetch_assoc()['id'];
editor_check($newid!==$id,'Licensed package saves a new revision');
$old=$db->query('SELECT * FROM subscription_plans WHERE id='.$id)->fetch_assoc();editor_check($old['name']==='Paket Editor Revisi'&&(int)$old['is_active']===0&&(int)$db->query('SELECT plan_id FROM tenant_subscriptions WHERE id='.$sid)->fetch_assoc()['plan_id']===$id,'Existing licence retains original package');
editor_check($db->query("SELECT * FROM subscription_plan_features WHERE plan_id=$id AND feature_code='social_aid'")->num_rows===1&&$db->query("SELECT * FROM subscription_plan_features WHERE plan_id=$newid AND feature_code='social_aid'")->num_rows===0,'Old feature entitlements preserved');
$audit=$db->query("SELECT * FROM subscription_audit_logs WHERE action='plan_edit' ORDER BY id DESC LIMIT 1")->fetch_assoc();editor_check((int)json_decode($audit['after_json'],TRUE)['plan_id']===$newid&&strpos($audit['before_json'],'Paket Editor Revisi')!==FALSE,'Edit audit records original and resulting package');
$original=array();foreach(array('subscription_basic_name','subscription_page_title','subscription_page_subtitle') as $key){$s=$db->prepare('SELECT setting_value FROM settings WHERE setting_key=?');$s->bind_param('s',$key);$s->execute();$original[$key]=$s->get_result()->fetch_assoc();}
$p->go('platform/paket',array('action'=>'presentation','subscription_basic_name'=>'Gratis Lingkungan','subscription_page_title'=>'Paket Lingkungan Saya','subscription_page_subtitle'=>'Kelola layanan lingkungan.'));$a->go('admin/langganan');editor_check(strpos($a->html,'Gratis Lingkungan')!==FALSE&&strpos($a->html,'Paket Lingkungan Saya')!==FALSE,'Basic name and page text editable');
foreach($original as $key=>$row){$s=$db->prepare('DELETE FROM settings WHERE setting_key=?');$s->bind_param('s',$key);$s->execute();if($row){$s=$db->prepare('INSERT INTO settings(setting_key,setting_value)VALUES(?,?)');$s->bind_param('ss',$key,$row['setting_value']);$s->execute();}}
$db->query('DELETE FROM tenant_subscriptions WHERE id='.$sid);
echo "Editable packages validated on isolated DB only.\n";
